#!/usr/bin/env node
/**
 * Tests for workflows/review-large.js: the cost guard. The saved workflow runs as the body of an
 * async function whose parameters are the orchestration primitives, so the test does the same with
 * stubs for `agent`, `pipeline`, `parallel`, `phase` and `log` and counts what would be spawned.
 * Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SOURCE = readFileSync(join(dirname(fileURLToPath(import.meta.url)), '..', 'workflows', 'review-large.js'), 'utf8')
  .replace(/^export /, '');
const AsyncFunction = (async () => {}).constructor;

/** Runs the workflow on `count` fake files; returns what it spawned, logged and returned. */
async function dryRun(count, extra = {}, handler = null, noFiles = false) {
  const files = noFiles ? undefined : Array.from({ length: count }, (_, i) => `src/f${i}.cs`);
  const spawned = [];
  const logs = [];
  const agent = async (_prompt, opts = {}) => {
    spawned.push({ ...opts, prompt: _prompt });
    if (handler) { const h = await handler(opts, _prompt); if (h !== undefined) return h; }
    return opts.label === 'merge the reviews into one report' ? 'REPORT' : { status: 'PASS', checked: 'read it', findings: [] };
  };
  const parallel = (thunks) => Promise.all(thunks.map((t) => t()));
  const pipeline = (items, stage) => Promise.all(items.map((item, i) => stage(item, item, i)));
  const run = new AsyncFunction('args', 'agent', 'parallel', 'pipeline', 'phase', 'log', 'budget', 'workflow', SOURCE);
  const out = await run({ range: 'origin/main...HEAD', files, ...extra }, agent, parallel, pipeline, () => {}, (m) => logs.push(m), {}, null);
  const reviewers = spawned.filter((o) => o.agentType === 'code-reviewer');
  return { out, logs, reviewers, spawned };
}

test('30 files: 3 groups + 1 whole-change reviewer + 1 merger, the count logged before any reviewer runs', async () => {
  const { logs, reviewers, spawned } = await dryRun(30, { effort: 'xhigh', modelB: 'opus' });
  assert.equal(reviewers.length, 4);
  assert.equal(reviewers.filter((r) => r.model === 'opus').length, 1);
  assert.equal(spawned.length, 5, '3 groups + 1 whole + the merger');
  assert.ok(logs.some((l) => l === '30 files -> 3 group reviewers (sonnet) + 1 whole-change reviewer (opus) + 1 merger = 5 agents'), logs.join('\n'));
});

test('100 files are still 3 groups: the files per group grow, no refusal', async () => {
  const { reviewers, out } = await dryRun(100, { effort: 'low' });
  assert.equal(reviewers.length, 4);
  assert.equal(out, 'REPORT');
  const groups = reviewers.filter((r) => r.model === undefined);
  assert.equal(groups.length, 3);
  assert.deepEqual(groups.map((g) => Number(/These (\d+) file/.exec(g.prompt)[1])), [33, 33, 34]);
});

test('filesPerReviewer defaults to 10 and sets the group count under the cap of 3', async () => {
  assert.equal((await dryRun(10)).reviewers.length, 2, '1 group + whole');
  assert.equal((await dryRun(11)).reviewers.length, 3, '2 groups + whole');
  assert.equal((await dryRun(12, { filesPerReviewer: 3 })).reviewers.length, 4, 'capped at 3 groups');
});

test('the files of one directory land in one group', async () => {
  const files = [...['z', 'a', 'm'].flatMap((d) => Array.from({ length: 10 }, (_, i) => `src/${d}/f${i}.cs`))];
  const { reviewers } = await dryRun(0, { files });
  const groups = reviewers.filter((r) => r.label !== 'whole change (cross-file)');
  assert.equal(groups.length, 3);
  for (const g of groups) {
    const scope = g.prompt.split('\n')[0];
    const dirs = new Set([...scope.matchAll(/'(src\/\w)\//g)].map((m) => m[1]));
    assert.equal(dirs.size, 1, scope);
  }
});

test('a cut snaps to a directory boundary within half a chunk: 11 files of one directory straddling a balanced cut stay together', async () => {
  const dir = (d, n) => Array.from({ length: n }, (_, i) => `src/${d}/f${i}.cs`);
  const { reviewers } = await dryRun(0, { files: [...dir('a', 5), ...dir('m', 11), ...dir('z', 14)] });
  const groups = reviewers.filter((r) => r.label !== 'whole change (cross-file)');
  assert.equal(groups.length, 3);
  const inM = groups.map((g) => (g.prompt.split('\n')[0].match(/'src\/m\//g) ?? []).length);
  assert.deepEqual(inM.filter((n) => n > 0), [11], inM.join(','));
});

test('a single directory of 30 files has no boundary to snap to: still 3 non-empty groups', async () => {
  const { reviewers } = await dryRun(30);
  const groups = reviewers.filter((r) => r.label !== 'whole change (cross-file)');
  assert.deepEqual(groups.map((g) => Number(/These (\d+) file/.exec(g.prompt)[1])), [10, 10, 10]);
});

test('B reviews the whole range at any effort, on modelB, and the groups know the full list', async () => {
  for (const effort of ['low', 'xhigh']) {
    const { reviewers } = await dryRun(30, { effort, modelB: 'fable' });
    const whole = reviewers.filter((r) => r.label === 'whole change (cross-file)');
    assert.equal(whole.length, 1, effort);
    assert.equal(whole[0].model, 'fable');
    assert.equal(whole[0].effort, effort);
    assert.match(whole[0].prompt, /f29\.cs/);
    assert.match(whole[0].prompt, /groups cover per-file defects/);
    const groups = reviewers.filter((r) => r !== whole[0]);
    assert.equal(groups.length, 3);
    assert.ok(groups.every((g) => g.model === undefined && /All the changed files: .*f29\.cs/.test(g.prompt) && /read them in full/.test(g.prompt)));
  }
});

test('past 60 files the briefs carry the count and the directories, not the list', async () => {
  const { reviewers } = await dryRun(61);
  assert.ok(reviewers.every((r) => /The change has 61 files in: src\//.test(r.prompt) && !/All the changed files/.test(r.prompt)));
});

test('reviewers get the effort; the merger runs on sonnet', async () => {
  const { reviewers, spawned } = await dryRun(6, { effort: 'high' });
  assert.ok(reviewers.every((r) => r.effort === 'high'));
  assert.equal(spawned.find((o) => o.label === 'merge the reviews into one report').model, 'sonnet');
});

test('modelB outside the allowed models is refused before any spawn', async () => {
  const { out, spawned } = await dryRun(6, { effort: 'high', modelB: 'gpt' });
  assert.match(out, /modelB "gpt" is not one of/);
  assert.equal(spawned.length, 0);
});

test('a null scope agent is an error message, not "no changed files"', async () => {
  const { out } = await dryRun(0, {}, (o) => (o.label === 'list the files to review' ? null : undefined), true);
  assert.match(out, /scope step failed: pass files or retry/);
});

test('a rejecting scope agent is the same error', async () => {
  const { out } = await dryRun(0, {}, (o) => { if (o.label === 'list the files to review') throw new Error('boom'); }, true);
  assert.match(out, /scope step failed/);
});

test('an empty scope answer is still "no changed files"', async () => {
  const { out } = await dryRun(0, {}, (o) => (o.label === 'list the files to review' ? { files: [] } : undefined), true);
  assert.match(out, /no changed files/);
});

test('a rejecting reviewer is a gap, the merger still runs', async () => {
  const { out, spawned } = await dryRun(6, {}, (o) => { if (o.agentType === 'code-reviewer') throw new Error('boom'); });
  assert.equal(out, 'REPORT');
  const merge = spawned.find((o) => o.label === 'merge the reviews into one report');
  assert.match(merge.prompt, /BLOCKED/);
});

test('a null merger returns the raw findings table', async () => {
  const finding = { title: 'Rotto', anchor: 'src/a.cs:3', category: 'correctness', verdict: 'PLAUSIBLE', status: 'todo', priority: 'P2', failure: 'x', evidence: 'y' };
  const { out } = await dryRun(6, {}, (o) => (o.label === 'merge the reviews into one report' ? null : o.agentType === 'code-reviewer' ? { status: 'ISSUES', findings: [finding] } : undefined));
  assert.match(out, /merger returned nothing/);
  assert.ok(out.includes('| 1 | P2 | CONFIRMED | correctness | src/a.cs:3 | Rotto | A+B |'), out);
});

test('A and B findings on the same anchor reach the merger as one CONFIRMED, checked is capped', async () => {
  const finding = { title: 'Rotto', anchor: 'src/a.cs:3', category: 'correctness', verdict: 'PLAUSIBLE', status: 'todo', priority: 'P2', failure: 'x', evidence: 'y' };
  const { spawned } = await dryRun(6, { effort: 'xhigh' }, (o) => (o.agentType === 'code-reviewer'
    ? { status: 'ISSUES', checked: 'c'.repeat(1000), findings: [finding] } : undefined));
  const prompt = spawned.find((o) => o.label === 'merge the reviews into one report').prompt;
  const input = JSON.parse(prompt.slice(prompt.indexOf('Results (JSON):') + 16));
  assert.equal(input.findings.length, 1);
  assert.equal(input.findings[0].foundBy, 'A+B');
  assert.equal(input.findings[0].verdict, 'CONFIRMED');
  assert.ok(input.workers.every((w) => w.checked.length === 300));
});
